const ComponentName: React.FC<ComponentNameProps> = ({
  backgroundColor = "#000000",
  transparentBackground = false,
  durationInSeconds = 5,
  labelColor = "#0d1322",
  titleText = "JULZLUXE SAMPLERS",
  subtitleText = "AVAILABLE TO ORDER NOW",
  scents = [
    { name: "Vapo Ru" },
    { name: "Sacred Woods" },
    { name: "Morning Brew" }
  ]
}) => {
  const frame = useCurrentFrame();
  const { width, height, durationInFrames } = useVideoConfig();
  const s = Math.min(width, height) / 1080;
  
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Global slow camera push
  const cameraScale = interpolate(frame, [0, durationInFrames], [1, 1.15], {
    extrapolateRight: "clamp"
  });

  // Top Text Fade
  const textOpacity = interpolate(frame, [80, 110], [0, 1], {
    extrapolateLeft: "clamp", extrapolateRight: "clamp"
  });

  // Center coordinate of the setup
  const cx = width / 2;
  const cy = height * 0.65;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, overflow: "hidden", transition: "none" }}>
      <div style={{
        position: "absolute",
        width: "100%", height: "100%",
        transform: `scale(${cameraScale})`,
        transformOrigin: `50% ${cy}px`,
        transition: "none"
      }}>
        
        {/* Top Typography */}
        <div style={{
          position: "absolute",
          top: height * 0.16,
          width: "100%",
          display: "flex", flexDirection: "column", alignItems: "center", gap: `${16 * s}px`,
          opacity: textOpacity,
          transition: "none"
        }}>
          <div style={{ fontFamily: playfairFamily, fontSize: `${44 * s}px`, color: "#fff", letterSpacing: `${6 * s}px`, transition: "none" }}>
            {titleText}
          </div>
          <svg width={24 * s} height={24 * s} viewBox="0 0 24 24" style={{ transition: "none" }}>
            <path d="M 12 0 L 16 12 L 12 24 L 8 12 Z" fill="#fff" opacity={0.6} />
          </svg>
          <div style={{ fontFamily: interFamily, fontSize: `${16 * s}px`, color: "#ccc", letterSpacing: `${8 * s}px`, transition: "none" }}>
            {subtitleText}
          </div>
        </div>

        {/* Candles Wrapper (Positions relative to center cx, cy) */}
        <div style={{ position: "absolute", left: cx, top: cy, transition: "none" }}>
          
          <Candle
            id={1} s={s} frame={frame} labelColor={labelColor}
            scentName={scents[0]?.name || "Vapo Ru"}
            startX={-800 * s} startY={-200 * s} startScale={1}
            endX={-340 * s - 160 * s} endY={-40 * s}
            delay={0} zIndex={10} igniteFrame={45}
          />

          <Candle
            id={3} s={s} frame={frame} labelColor={labelColor}
            scentName={scents[2]?.name || "Morning Brew"}
            startX={800 * s} startY={-200 * s} startScale={1}
            endX={340 * s - 160 * s} endY={-40 * s}
            delay={10} zIndex={10} igniteFrame={65}
          />

          {/* Center candle rendered last/higher zIndex to pass in front during swoop */}
          <Candle
            id={2} s={s} frame={frame} labelColor={labelColor}
            scentName={scents[1]?.name || "Sacred Woods"}
            startX={-160 * s} startY={800 * s} startScale={2.5}
            endX={-160 * s} endY={0}
            delay={5} zIndex={20} igniteFrame={55}
          />
          
        </div>

      </div>
    </AbsoluteFill>
  );
};

export default ComponentName;